#!/usr/bin/env bash
# assert-test-in-diff.sh — WAR worker test-floor guard (M2, spec §3.1).
#
# Usage: assert-test-in-diff.sh <integration-base> <task-branch> \
#          [--repo <git-dir>] [--pattern <glob-set>]
# (--repo is test-only: points git at a fixture repo; production invokes from the task-worktree cwd)
#
# Compute `git diff --name-only <base>...<branch>` (three-dot symmetric diff —
# exactly what the task branch added relative to the integration base).
#
# Exit codes (load-bearing contract):
#   0 — at least one changed path matches the test pattern (test found in
#       diff); stdout carries ALL matched test paths, one per line — the
#       refiner's MergeResult.mappedTests source
#   1 — no matching test in the diff (the "no-test" route; not an error).
#       stdout stays the empty summary; stderr MAY carry the near-miss
#       diagnostic (see NEAR-MISS DIAGNOSTIC below) — advisory, never routed on.
#   2 — git/ref error (HARD error; NOT a "no-test" signal; caller must not treat
#       as "no test found" — it means the diff could not be computed)
#
# DEFAULT PATTERN = EXACTLY the resolved gate's discovery set (operator decision
# 2026-06-29 — supersedes the spec §3.1 broad union, which red-team proved
# over-counts):
#   - skills/**/*.test.mjs   (the node --test glob, PATH-SCOPED to skills/,
#                             DEPTH-AGNOSTIC — mirrors the unbounded glob)
#   - **/*.test.sh           (the repo-wide bash-suite find, *.test.sh anywhere,
#                             EXCLUDING node_modules/, .git/, and .claude/ — mirrors
#                             `find . -name '*.test.sh' -not -path '*/node_modules/*'
#                              -not -path '*/.git/*' -not -path '*/.claude/*'`)
#
# ponytail: default == gate-discovery set so the floor can never be satisfied
# by a test the gate ignores. Override via --pattern for repos that use other
# test types (.test.js, pytest, etc). The gate's resolveGate in war-config.mjs
# is the authoritative source; this default mirrors it verbatim.
#
# --pattern IS LOAD-BEARING: the value is PER-PHASE-RESOLVED from the run's
# overrides.testPattern config — pinned at Setup, and an --afk run's rejected
# Setup proposal can still be re-checked and adopted at a later phase launch —
# then threaded into each phase's Workflow and passed through to this floor by
# the refiner.
# A custom --pattern does NOT replace the floor wholesale — the gate's
# UNCONDITIONAL *.test.sh discovery arm (resolveGate appends
# `find . -name '*.test.sh' ...` to EVERY declared gate) is UNIONED into any
# custom set (match_sh_suite), so a *.test.sh suite always satisfies the floor.
# The union preserves floor ⊆ gate for the gate's unconditional discovery,
# whatever pattern is in force for the phase.
#
# NEAR-MISS DIAGNOSTIC (spec §4, D4/D5) — EXIT-1 PATH ONLY, STDERR ONLY.
# When nothing matched, the SAME changed-file list is re-scanned against a
# FIXED, documented set of test-shaped conventions:
#   *.test.*   *.spec.*   *_test.*   plus basename-prefix  test_*
# (node / pytest / go conventions, at equal cost; never derived from the repo —
# a floor-time derivation would make the verdict depend on tree state outside
# the diff). Any hit is printed on stderr next to the ACTIVE pattern set, so a
# pattern/target-repo mismatch is visible on the FIRST no-test instead of after
# three add-test rounds (#983).
# DIAGNOSTIC-ONLY: the scan can never block, change an exit code, or write to
# stdout — a false positive costs exactly one stderr line. No scan on exit 0
# (nothing to explain) and none on the exit-2 die path (a diff that could not be
# computed has no file list).
=== GATE_DISCOVERY ===
    : { source: 'default', seats: defaultRoster }
}

// GATE_DISCOVERY_TOKEN: a short stable substring of the discovery find clause (the `-name '*.test.sh'`
// neighborhood), declared once in resolveGate's own module scope and used BOTH to build the discovery
// string AND as the idempotence detector — so composer and detector cannot drift from each other by
// construction. The inline workflow-template.js mirror duplicates the same pairing.
const GATE_DISCOVERY_TOKEN = `-name '*.test.sh'`
// Self-discovering multi-runner gate (F12), IDEMPOTENT (engine-owned composition, ADR 0036).
// Given the declared base command (e.g. `node --test 'skills/**/*.test.mjs'`), returns
// a portable shell string that runs the declared gate AND discovers + runs every *.test.sh
// found in the repo tree (excluding node_modules, .git, and .claude). The bash suites are
// sorted and executed in order; any non-zero exit aborts immediately (|| exit 1).
// The .claude/ exclusion keeps a repo-root gate run from executing the ~100 stale duplicate
// suites under .claude/worktrees/ (WAR's own task worktrees).
// COUPLING (D9, #1372/#1343): the `|| exit 1` abort is load-bearing beyond gate semantics — a red
// bash suite stops the discovery loop, so suites after the abort point print no per-file banner and
// the captured gate log's bash half is truncated. The gate-audit seat prompts' truncation clause
// (mappedTestsLine/authMappedLine in workflow-template.js, plus the agents/war-auditor.md D7 bullet)
// depends on exactly this fail-fast shape to read a post-abort zero-hit grep as soft
// cannot-confirm rather than a provably-unrun hold. Change one, revisit the other.
// Empty/null/falsy declaredGate → the discovery clause ALONE (no leading &&).
// IDEMPOTENT: a declaredGate that ALREADY carries the discovery clause (detected via
// GATE_DISCOVERY_TOKEN) is returned UNCHANGED, so resolveGate(resolveGate(g)) === resolveGate(g).
// The engine now normalizes plan.gate through this composition AND the Lead still pre-resolves via
// --resolve-gate; idempotence makes that double composition harmless by construction (belt-and-suspenders).
// MIRRORED inline in workflow-template.js. Keep in sync.
export function resolveGate(declaredGate) {
  const discovery = [
    `for f in $(find . -type f ${GATE_DISCOVERY_TOKEN} -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/.claude/*' | sort);`,
    `do printf '\\n== gate(bash): %s ==\\n' "$f" && bash "$f" || exit 1; done`,
  ].join(' ')
  if (!declaredGate) return discovery
  if (declaredGate.includes(GATE_DISCOVERY_TOKEN)) return declaredGate
  return `${declaredGate} && ${discovery}`
}

// --- CLI ---------------------------------------------------------------------
// node war-config.mjs --preset <name>            -> print a filled preset config (stdout)
// node war-config.mjs --resolve-gate <cmd>       -> print the self-discovering gate string
// node war-config.mjs <path>   [--fill-defaults] -> validate a file; print filled config or "valid"
// node war-config.mjs --stdin  [--fill-defaults] -> validate JSON from stdin; same output
// exit 0 = valid; exit 1 = invalid (errors on stderr) or usage error
async function main(argv) {
  const args = argv.slice(2)
  const has = f => args.includes(f)
  const valOf = f => { const i = args.indexOf(f); return i >= 0 ? args[i + 1] : undefined }

  if (has('--help') || args.length === 0) {
    process.stdout.write('usage: war-config.mjs (--preset <name> | <path> | --stdin | --resolve-gate <cmd>) [--fill-defaults]\n')
    process.exit(args.length === 0 ? 1 : 0)
  }

  if (has('--resolve-gate')) {
    const cmd = valOf('--resolve-gate') ?? ''
    process.stdout.write(resolveGate(cmd) + '\n')
